INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d06ecad64dcdc5811386','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','290','Mixed/Unclassified','Australian Medical Council
MCQ 3.152
An X-ray examination of a 45-year-old man presenting with bone pain shows an
expanding rarefying bone lesion of the right humerus which is diagnosed as anaplastic
carcinoma on biopsy. No other bony lesions are found. The patient has had continuous
fever for the past three weeks. From which one of the following primary sites is this
metastatic lesion most likely to have arisen?
. Kidney.
. Liver.
. Testis.
. Stomach.
. Prostate.
MCQ 3.153
A 17-year-old youth presents with a one week history of discomfort in the right side
of his scrotum. He first noticed his symptoms after a game of football, during which
he collided with an opponent and thought he may have been hit in his groin. On
examination the left side of the scrotum and contents are normal and on the right side
there is a non-tender 8cm swelling. The right testis cannot be clearly felt separately
from the scrotal lump. The cord and hernial orifices appear normal. Which one of the
following is the most appropriate next step in management?','{"A":"Scrotal support.","B":"Antibiotics.","C":"Fine needle aspiration cytology.","D":"Urinalysis and culture.","E":"Scrotal ultrasound.\n\nMCQ 3.154\n\nPrior to endoscopic removal of a 2cm radio-opaque ureteric calculus, which one of\nthe following is the most important investigation?\n\n. Haemoglobin estimation.\n\n. Urine culture.\n\n. Plain X-ray examination on the way to the operating room.\n. Serum uric acid estimation.\n\n. Serum calcium estimation.\n\nMCQ 3.155\n\nA 65-year-old man is diagnosed with carcinoma of the prostate and the disease\nstaged by Tumour (T), Node involvement (N) and Metastasis (M) as 73, NO, MO\nwith invasion of the seminal vesicles. Which one of the following would be the most\nappropriate potentially curative treatment to offer the patient?"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.152","duplicate_group_id":"exact-bb6421040587","duplicate_sources":[{"record_id":"d06ecad64dcdc5811386","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":290,"source_qid":"3.152"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"d06ecad64dcdc5811386","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":290,"source_qid":"3.152","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nMCQ 3.152\nAn X-ray examination of a 45-year-old man presenting with bone pain shows an\nexpanding rarefying bone lesion of the right humerus which is diagnosed as anaplastic\ncarcinoma on biopsy. No other bony lesions are found. The patient has had continuous\nfever for the past three weeks. From which one of the following primary sites is this\nmetastatic lesion most likely to have arisen?\n. Kidney.\n. Liver.\n. Testis.\n. Stomach.\n. Prostate.\nMCQ 3.153\nA 17-year-old youth presents with a one week history of discomfort in the right side\nof his scrotum. He first noticed his symptoms after a game of football, during which\nhe collided with an opponent and thought he may have been hit in his groin. On\nexamination the left side of the scrotum and contents are normal and on the right side\nthere is a non-tender 8cm swelling. The right testis cannot be clearly felt separately\nfrom the scrotal lump. The cord and hernial orifices appear normal. Which one of the\nfollowing is the most appropriate next step in management?","options":{"A":"Scrotal support.","B":"Antibiotics.","C":"Fine needle aspiration cytology.","D":"Urinalysis and culture.","E":"Scrotal ultrasound.\n\nMCQ 3.154\n\nPrior to endoscopic removal of a 2cm radio-opaque ureteric calculus, which one of\nthe following is the most important investigation?\n\n. Haemoglobin estimation.\n\n. Urine culture.\n\n. Plain X-ray examination on the way to the operating room.\n. Serum uric acid estimation.\n\n. Serum calcium estimation.\n\nMCQ 3.155\n\nA 65-year-old man is diagnosed with carcinoma of the prostate and the disease\nstaged by Tumour (T), Node involvement (N) and Metastasis (M) as 73, NO, MO\nwith invasion of the seminal vesicles. Which one of the following would be the most\nappropriate potentially curative treatment to offer the patient?"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"bb64210405877e5174996e82c30289e401dfc683","duplicate_group_id":"exact-bb6421040587","duplicate_sources":[{"record_id":"d06ecad64dcdc5811386","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":290,"source_qid":"3.152"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
