INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('cb8ed3ef2a4014a979fd','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','292','Mixed/Unclassified','Australian Medical Council
Section 3 — Adult Health and Aged Care
MCQ 3.159
A 64-year-old man presents with a two-day history of pain in the left side of the scrotum.
He has no other symptoms and is normally in good health. On examination he has
a temperature of 38.6°C. The left hemiscrotum is reddened and tender to touch.
The testis and cord appear enlarged and thickened. Which one of the following
investigations will be of most diagnostic help?','{"A":"Gram stain of urethral discharge.","B":"Urine culture.","C":"Doppler flow studies.","D":"Radionuclide scintigraphy.","E":"Fine needle aspiration cytology (FNAC).\n\n=orom:\n\nMCQ 3.160\n\nSS aS SSS ss SSSssSNSsSSSs\n\nA 76-year-old man attends the Emergency Department with a history of painless\npassage of red urine. He has been unwell for a few days and finds it difficult to walk now.\nHe has had a cough and yellow sputum, for which he has been taking erythromycin\nfor the past week. His background history includes ischaemic heart disease (treated\nwith metoprolol, aspirin and mononitrate) and hypercholesterolaemia treated with\nsimvastatin.\n\nOn examination he is afebrile, pulse is 80/min, blood pressure is 130/80mmHg and\nchest is clinically clear. Heart sounds are normal. He finds it difficult to walk. His\nelectrocardiogram (ECG) is normal. Urine dipstick (Multistix®) shows blood ++++. Urine\nmicroscopy shows no cells or bacilli and culture is arranged.\n\nHis serum biochemistry is as shown:\n\nUrea *11.2mmol/L — (3.0-8.0)\nCreatinine *O.11mmol/L (0.06-0.12)\nBilirubin (Total) *13mmol/L (<20)\n\nGamma glutamy! trans- —15mmol/L (<50)\nferase (GGT)\n\nAlkaline phosphatase 92mmol/L (25-100)\n(ALP)\n\nAlanine aminotrans- *4A56mmol/L — (<35)\nferase (ALT)\n\nAspartate aminotrans- *1085mmol/L (<40)\nferase (AST)\n\nLactate dehydrogenase *1311mmol/L (110-230)\n\n(LD)\nCreatine kinase (CK) *32767U/L (60-220)\nC-Reactive Protein *17.6mg/L (<3.0)\n\nWhich one of the following is the most likely diagnosis?"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.159","duplicate_group_id":"exact-931ea15f35e7","duplicate_sources":[{"record_id":"cb8ed3ef2a4014a979fd","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Ve