ting eight-hour gap. His only previous history was of intermittent palpitations and hypertension, for which he has been treated with perindopril/indapamide 4/1.25 mg daily and atenolol 50 mg daily. Which one of the following is the most likely cause of his loss of memory?","options":{"A":"A cardiac arrhythmia.","B":"Left internal carotid artery stenosis.","C":"Transient global amnesia.","D":"Complex partial seizure.","E":"Wernicke encephalopathy."},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"human_visual_review_batch001","text_method":"manual_visual_transcription","parser_version":"manual-review-batch001-2026-09-24","manual_review_batch":"001","manual_review_source_key":"","stem_hash":"b6fac5c2d27ed6e5acc6f74af55ecb7a9bda8ef8b305a1c8640e1ec5d6e1a3d9"}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
