INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('cb6cc7b1c471be25da4c','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','303','Mixed/Unclassified','Australian Medical Council
Section 3 — Adult Health and Aged Care
MCQ 3.174
An abattoir worker has presented with a one-week history of sore throat, chills and
sweats, associated with diarrhoea and vomiting. He initially had a nonproductive
cough but now has developed pneumonia. Several other workers from the same
meat works have also been ill and you suspect the patient may have Q fever (Coxiella
burnetii infection). Which one of the following investigations would be most useful in
confirming this diagnosis?
. Culture of sputum.
. Blood culture.
. Serum antibody levels.
. Stool culture and cytology.
. Sputum cytology.
MCQ 3.175
A 60-year-old man is on the waiting list for colonic resection for cancer. Which one of
the following is the most appropriate time to begin the administration of prophylactic
antibiotic therapy for his intestinal surgery?','{"A":"Two days prior to the operation.","B":"During anaesthetic induction prior to the operation.","C":"As the incision is being made.","D":"If contamination is found during the operation.","E":"After closure of the abdomen.\n\nMCQ 3.176\n\nA 58-year-old man presented to the\nEmergency Department with a 36-hour\nhistory of pain and swelling in his leg. Twenty\nyears ago he fractured his tibia and fibula in\nthat leg and was in hospital for three weeks.\nHe has long-standing Type 1 diabetes, which\nis well controlled on insulin. Pulse rate is 96/\nmin, BP 144/92mmHg, and temperature\n37.8°C. The appearance of his leg is shown\nin the illustration. He has been commenced\non intravenous penicillin and flucloxacillin.\nWhich one of the following is the most\nimportant next step in management?\n\n. Bed rest.\n\n. Warfarin.\n\n. Firm compression bandaging.\n\n. Surgical incision and drainage.\n\n. Wide excision of the discoloured area."}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.174","duplicate_group_id":"exact-7f63f979c246","duplicate_sources":[{"record_id":"cb6cc7b1c471be25da4c","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":303,"source_qid":"3.174"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"cb6cc7b1c471be25da4c","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":303,"source_qid":"3.174","domain_hint":"Mixed/Unclassified","