INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ba4a07f59a0f6cf10d17','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','307','Mixed/Unclassified','Australian Medical Council _
MCQ 3.179
A 75-year-old woman has taken lithium carbonate without complications for many
years because of bipolar affective disorder. A nonsteroidal anti-inflammatory
drug (NSAID) was recently prescribed for osteoarthritic pain in the right knee.
Over the subsequent weeks she lost her appetite and became ataxic, nauseated
and tremulous. Which one of the following is the most likely explanation of her
symptoms?','{"A":"The absorption of her drugs has been markedly affected by her age.","B":"These symptoms are typical of NSAID toxicity.","C":"Lithium is inhibiting the clearance of the NSAID from the body.","D":"The NSAID is decreasing the renal clearance of lithium.","E":"These symptoms do not suggest lithium toxicity."}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.179","duplicate_group_id":"exact-064d662a2f1b","duplicate_sources":[{"record_id":"ba4a07f59a0f6cf10d17","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":307,"source_qid":"3.179"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"ba4a07f59a0f6cf10d17","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":307,"source_qid":"3.179","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council _\nMCQ 3.179\nA 75-year-old woman has taken lithium carbonate without complications for many\nyears because of bipolar affective disorder. A nonsteroidal anti-inflammatory\ndrug (NSAID) was recently prescribed for osteoarthritic pain in the right knee.\nOver the subsequent weeks she lost her appetite and became ataxic, nauseated\nand tremulous. Which one of the following is the most likely explanation of her\nsymptoms?","options":{"A":"The absorption of her drugs has been markedly affected by her age.","B":"These symptoms are typical of NSAID toxicity.","C":"Lithium is inhibiting the clearance of the NSAID from the body.","D":