INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('e7cc5f0dfbdea306a783','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','322','Mixed/Unclassified','Australian Medical Council
Section 3 — Adult Health and Aged Care
MCQ 3.206
An 18-year-old university student, who had a suction curettage performed for an
unwanted pregnancy which occurred after a university party, presents to you four
days later with a temperature of 38.4°C and a purulent vaginal discharge. Which one
of the following organisms is the most likely cause of her symptoms?
A. Mixed infection with Chlamydia trachomatis and vaginal pathogens.
B. N. gonorrhoea alone.
C. Chlamydia trachomatis alone.
D. E. colialone.
Mycoplasma hominis alone.
ua
MCQ 3.207
A 25-year-old woman (gravida 0, para 0), who is not sexually active and has cycles
varying between 32 and 35 days in length, presents because of intermittent lower
abdominal pain. Her last normal menstrual period commenced three weeks ago. You
arranged a pelvic ultrasound examination, which showed that the uterus and right
ovary are of normal size and appearance, but that there is a cystic structure in the
left ovary. This structure is 4.5cm in diameter, unilocular and thin walled. Which one of
the following is the most likely cause of the ultrasound findings?','{"A":"A developing follicle which is about to ovulate.","B":"A follicular cyst.","C":"Acorpus luteum cyst.","D":"A benign cystic teratoma.","E":"An endometriotic cyst.\n\nMCQ 3.208\n\nA 58-year-old woman presents with mild lower abdominal discomfort. She has been\nmenopausal for eight years. Vaginal examination three years ago was normal. Now a\n6cm mass is palpable in the left ovarian region. Which one of the following is the most\nappropriate next step in management?\n\nParenteral progestogens.\n\nPapanicolaou (Pap) smear and review in six weeks.\n. Papanicolaou (Pap) smear and review in six months.\nX-ray to evaluate osteoporosis.\n\nAdmission to hospital for early surgical exploration.\n\nMOQOR>\n\nMCQ 3.209\n\nA 32-year-old woman presents with a two-year history of secondary infertility. Her\nfirst child was fathered by the same partner, she conceived spontaneously and was\ndelivered normally after a short labour. The child is now three years old. She has always\nhad irregular menstrual cycles, with periods occurring every three to four months. A\npelvic ultrasound examination shows 15-20 small cysts (4-6mm in diameter) in each\novary. Her partner’s semen analysis shows a sperm count of ten million per mL, with\n50% motility and 30% abnormal forms. Which one of the following is the most appro-\npriate next step in the treatment of her infertility2"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.206","duplicate_group_id":"exact-5d9c9ba8ccd5","duplicate_sources":[{"record_id":"e7cc5f0dfbdea306a783","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":322,"source_qid":"3.206"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"e7cc5f0dfbdea306a783","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":322,"source_qid":"3.206","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 3 — Adult Health and Aged Care\nMCQ 3.206\nAn 18-year-old university student, who had a suction curettage performed for an\nunwanted pregnancy which occurred after a university party, presents to you four\ndays later with a temperature of 38.4°C and a purulent vaginal discharge. Which one\nof the following organisms is the most likely cause of her symptoms?\nA. Mixed infection with Chlamydia trachomatis and vaginal pathogens.\nB. N. gonorrhoea alone.\nC. Chlamydia trachomatis alone.\nD. E. colialone.\nMycoplasma hominis alone.\nua\nMCQ 3.207\nA 25-year-old woman (gravida 0, para 0), who is not sexually active and has cycles\nvarying between 32 and 35 days in length, presents because of intermittent lower\nabdominal pain. Her last normal menstrual period commenced three weeks ago. You\narranged a pelvic ultrasound examination, which showed that the uterus and right\novary are of normal size and appearance, but that there is a cystic structure in the\nleft ovary. This structure is 4.5cm in diameter, unilocular and thin walled. Which one of\nthe following is the most likely cause of the ultrasound findings?","options":{"A":"A developing follicle which is about to ovulate.","B":"A follicular cyst.","C":"Acorpus luteum cyst.","D":"A benign cystic teratoma.","E":"An endometriotic cyst.\n\nMCQ 3.208\n\nA 58-year-old woman presents with mild lower abdominal discomfort. She has been\nmenopausal for eight years. Vaginal examination three years ago was normal. Now a\n6cm mass is palpable in the left ovarian region. Which one of the following is the most\nappropriate next step in management?\n\nParenteral progestogens.\n\nPapanicolaou (Pap) smear and review in six weeks.\n. Papanicolaou (Pap) smear and review in six months.\nX-ray to evaluate osteoporosis.\n\nAdmission to hospital for early surgical exploration.\n\nMOQOR>\n\nMCQ 3.209\n\nA 32-year-old woman presents with a two-year history of secondary infertility. Her\nfirst child was fathered by the same partner, she conceived spontaneously and was\ndelivered normally after a short labour. The child is now three years old. She has always\nhad irregular menstrual cycles, with periods occurring every three to four months. A\npelvic ultrasound examination shows 15-20 small cysts (4-6mm in diameter) in each\novary. Her partner’s semen analysis shows a sperm count of ten million per mL, with\n50% motility and 30% abnormal forms. Which one of the following is the most appro-\npriate next step in the treatment of her infertility2"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","pregnan"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"5d9c9ba8ccd5835590cd9b120a864e3a3beb8f23","duplicate_group_id":"exact-5d9c9ba8ccd5","duplicate_sources":[{"record_id":"e7cc5f0dfbdea306a783","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":322,"source_qid":"3.206"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=ex