to conceive for the last three years. She has had previous fallopian tube surgery
after tubal obstruction had been diagnosed by laparoscopy, has amenorrhoea and
galactorrhoea, and had evidence of mild endometriosis involving the uterosacral
ligaments treated at the time of the tubal surgery. He has a severe and persistent
abnormality of the semen specimen. Which one of the following is the most appro-
priate management?','{"A":"She should be treated with the dopamine agonist bromocriptine.","B":"She should be treated with danazol.","C":"He should be treated with gonadotrophin injections.","D":"She should have further laparoscopic surgery.","E":"They should use intracytoplasmic sperm injection (ICSI) in IVF.\n\nMCQ 3.215"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[324],"source_qid":"3.213","duplicate_group_id":"exact-f076267023de","duplicate_sources":[{"record_id":"3c158f973d505ef6dc72","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":324,"source_qid":"3.213"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_multi_question_group","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"3c158f973d505ef6dc72","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":324,"supporting_pages":[324],"source_qid":"3.213","domain_hint":"Mixed/Unclassified","stem":"You are reviewing a couple who are both in their late twenties and have been trying\nto conceive for the last three years. She has had previous fallopian tube surgery\nafter tubal obstruction had been diagnosed by laparoscopy, has amenorrhoea and\ngalactorrhoea, and had evidence of mild endometriosis involving the uterosacral\nligaments treated at the time of the tubal surgery. He has a severe and persistent\nabnormality of the semen specimen. Which one of the following is the most appro-\npriate management?","options":{"A":"She should be treated with the dopamine agonist bromocriptine.","B":"She should be treated with danazol.","C":"He should be treated with gonadotrophin injections.","D":"She should have further laparoscopic surgery.","E":"They should use intracytoplasmic sperm injection (ICSI) in IVF.\n\nMCQ 3.215"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_multi_question_group","text_method":"tesseract","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"f076267023de18ed60eb7aac5fa67d9d3e711719","duplicate_group_id":"exact-f076267023de","duplicate_sources":[{"record_id":"3c158f973d505ef6dc72","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":324,"source_qid":"3.213"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
