INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('cec4c21d7e5a9ec35f92','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','325','Mixed/Unclassified','Australian Medical Council
Section 3 — Adult Health and Aged Care
One
1a
ap
gis
A cervical ectropion.
Chlamydial cervicitis.
. Acervical polyp.
Cervical intraepithelial neoplasia.
Cervical carcinoma.
MOOR >
MCQ 3.217
A healthy 52-year-old woman ceased menstruating three months ago and is now
complaining of hot flushes 10-12 times daily, irritability and difficulty sleeping. Which
one of the following treatments would be most likely to relieve her symptoms without
troublesome side effects?
A. Continuous daily oestrogen therapy, with medroxy progesterone acetate (MPA)
given daily for 12 days each month.
Continuous oestrogen therapy alone.
. Daily progestogen therapy with MPA.
Continuous therapy with oestrogen and MPA.
Daily treatment with diazepam.
mTMO0 2
MCQ 3.218
A couple decide to use the daily basal body temperature assessment (BBT) as their
method of contraception. During the last 12 months, she has had cycles varying in
length between 24 and 30 days, with periods lasting four days. They do not have any
sexual activity while she is menstruating. Which one of the following regimens would
be the most appropriate for minimising the likelihood of pregnancy?','{"A":"Intercourse day four to day nine, abstinence day 10 until two days after the\n\nemperature elevation of 0.4°C, intercourse thereafter.","B":"Intercourse day four to day seven, abstinence day eight until two days after the\n\nemperature elevation of 0.3°C, intercourse thereafter.","C":"Intercourse day four to day five, abstinence day six until two days after the temper-\nature elevation of 0.3°C, intercourse thereafter.","D":"No intercourse in the follicular phase of the cycle, commence intercourse two\ndays after temperature elevation of 0.1°C and continue thereafter.","E":"No intercourse in the follicular phase of the cycle, commence intercourse two\ndays after temperature elevation of 0.3°C and continue thereafter.\n\nMCQ 3.219\n\nA 60-year-old woman, who had three pregnancies before the age of 30 years,\ncomplains of incontinence of urine for the last 12 months. Because of this problem,\nshe has had to wear a ‘pad inside her panties all the time. She is not taking any\nhormone replacement therapy. Which one of the following symptoms would indicate\nthat the incontinence is probably genuine stress incontinence?\n\n307"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.217","duplicate_group_id":"exact-3a8e182938e2","duplicate_sources":[{"record_id":"cec4c21d7e5a9ec35f92","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":325,"source_qid":"3.217"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"cec4c21d7e5a9ec35f92","source_file":"96.Handbook of Multiple C