INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9a116caeb0963fd25800','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','326','Mixed/Unclassified','Australian Medical Council
. When she gets the feeling she has to void, she has to do so quickly or she wets
herself.
. Only small quantities of urine are lost each time she is incontinent.
. The incontinence often occurs at night when she is asleep.
. She did not have any incontinence during her pregnancies.
. She has the desire to empty her bladder again after an incontinence episode.
MCQ 3.220
A 58-year-old woman has an obviously palpable right adnexal mass detected for the
first time on pelvic examination. She had reached the menopause at the age of 50
years. A previous pelvic examination three years ago had been normal. Which one
of the following is the most likely diagnosis?','{"A":"Follicular ovarian cyst.","B":"Benign ovarian dermoid.","C":"Degenerating uterine fibroid.","D":"Endometrial carcinoma with metastases.","E":"Ovarian carcinoma.\n\nMCQ 3.221\n\nYou have just found a probable malignancy, involving the left ovary, on ultrasound\nexamination in a 50-year-old third generation Australian woman. This investigation\nwas performed because she had some intermittent lower abdominal pain. The report\nsuggests the ovarian lesion may represent metastatic disease. Which one of the\nfollowing is the most appropriate investigation likely to define the site of the primary\ntumour?\n\nA. Computed tomography (CT) of the abdomen.\nB. Ultrasound examination of the abdomen.\n\nC. Colonoscopy.\n\nD. Bilateral mammography.\n\nE. Chest X-ray.\n\nMCQ 3.222\n\nA 45-year-old woman presents with menorrhagia. Although her menstrual cycles are\nregular, for the last five years she has bled heavily for eight days each month and\nher haemoglobin level one month ago was 85g/L. She is already on iron therapy. In\naddition to the anaemia, she also has a past history of cervical intraepithelial neoplasia\ngrade 3 (CIN3), although her yearly smear test has been normal since laser treatment\nof this six years ago. She is also on treatment for hypertension. Clinical examination is\nnormal. She indicates she is not prepared to have an endometrial ablation performed,\nnor is she prepared to have a hysterectomy until she reaches the menopause. Which\none of the following medical treatments would be most appropriate for her to use\nbetween now and when she is likely to reach the menopause, at about the age of\n50 years?"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.220","duplicate_group_id":"exact-556da7fe046b","duplicate_sources":[{"record_id":"9a116caeb0963fd25800","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":326,"source_qid":"3.220"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"9a116caeb0963fd25800","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":326,"source_qid":"3.220","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\n. When she gets the feeling she has to void, she has to do so quickly or she wets\nherself.\n. Only small quantities of urine are lost each time she is incontinent.\n. The incontinence often occurs at night when she is asleep.\n. She did not have any incontinence during her pregnancies.\n. She has the desire to empty her bladder again after an incontinence episode.\nMCQ 3.220\nA 58-year-old woman has an obviously palpable right adnexal mass detected for the\nfirst time on pelvic examination. She had reached the menopause at the age of 50\nyears. A previous pelvic examination three years ago had been normal. Which one\nof the following is the most likely diagnosis?","options":{"A":"Follicular ovarian cyst.","B":"Benign ovarian dermoid.","C":"Degenerating uterine fibroid.","D":"Endometrial carcinoma with metastases.","E":"Ovarian carcinoma.\n\nMCQ 3.221\n\nYou have just found a probable malignancy, involving the left ovary, on ultrasound\nexamination in a 50-year-old third generation Australian woman. This investigation\nwas performed because she had some intermittent lower abdominal pain. The report\nsuggests the ovarian lesion may represent metastatic disease. Which one of the\nfollowing is the most appropriate investigation likely to define the site of the primary\ntumour?\n\nA. Computed tomography (CT) of the abdomen.\nB. Ultrasound examination of the abdomen.\n\nC. Colonoscopy.\n\nD. Bilateral mammography.\n\nE. Chest X-ray.\n\nMCQ 3.222\n\nA 45-year-old woman presents with menorrhagia. Although her menstrual cycles are\nregular, for the last five years she has bled heavily for eight days each month and\nher haemoglobin level one month ago was 85g/L. She is already on iron therapy. In\naddition to the anaemia, she also has a past history of cervical intraepithelial neoplasia\ngrade 3 (CIN3), although her yearly smear test has been normal since laser treatment\nof this six years ago. She is also on treatment for hypertension. Clinical examination is\nnormal. She indicates she is not prepared to have an endometrial ablation performed,\nnor is she prepared to have a hysterectomy until she reaches the menopause. Which\none of the following medical treatments would be most appropriate for her to use\nbetween now and when she is likely to reach the menopause, at about the age of\n50 years?"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","pregnan"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","record_type":"text_mcq","options_mode":"text","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"556da7fe046b1f61671c5f779f4d15626c722255","duplicate_group_id":"exact-556da7fe046b","duplicate_sources":[{"record_id":"9a116caeb0963fd25800","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":326,"source_qid":"3.220"}]}',0,'v2.9.4','2026-0