INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('281bf199ed44ad7ce283','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','329','Mixed/Unclassified','Australian Medical Council
MCQ 3.228
A young couple presents to you with infertility of nine months duration. They are
both 25 years old. Investigations show she is ovulating, a hysterosalpingogram is
normal, and his semen analysis results are as follows:
Semen volume AmL (2-6mL)
Sperm count *2 million/mL (>20 million)
Motility 10% (>40%)
Abnormal forms 90% (<60%)
These results are confirmed on a second semen specimen three months later. Which
one of the following is the most appropriate next step in management?','{"A":"Advise them to keep trying, as their infertility is of short duration.","B":"Treat him with injections of follicle stimulating hormone (FSH).","C":". Carry out intrauterine insemination of the wife with his semen.","D":". Carry out in vitro fertilisation (IVF) using intracytoplasmic sperm injection(ICSI).\nCarry out insemination of the wife with donor sperm.","E":"MOQ@>"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[329],"source_qid":"3.228","duplicate_group_id":"exact-491c4a0205e8","duplicate_sources":[{"record_id":"281bf199ed44ad7ce283","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":329,"source_qid":"3.228"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"281bf199ed44ad7ce283","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":329,"supporting_pages":[329],"source_qid":"3.228","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nMCQ 3.228\nA young couple presents to you with infertility of nine months duration. They are\nboth 25 years old. Investigations show she is ovulating, a hysterosalpingogram is\nnormal, and his semen analysis results are as follows:\nSemen volume AmL (2-6mL)\nSperm count *2 million/mL (>20 million)\nMotility 10% (>40%)\nAbnormal forms 90% (<60%)\nThese results are confirmed on a second semen specimen three months later. Which\none of the following is the most appropriate next step in management?","options":{"A":"Advise them to keep trying, as their infertility is of short duration.","B":"Treat him with injections of follicle stimulating hormone (FSH).","C":". Carry out intrauterine insemination of the wife with his semen.","D":". Carry out in vitro fertilisation (IVF) using intracytoplasmic sperm injection(ICSI).\nCarry out insemination of the wife with donor sperm.","E":"MOQ@>"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","duration","management"],"likely_visual_question":false,"parser_confidence":"medium","parser_mode":"v27_same_page_five_structural","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"491c4a0205e8bf95effc23c1037a55a63ba8b283","duplicate_group_id":"exact-491c4a0205e8","duplicate_sources":[{"record_id":"281bf199ed44ad7ce283","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":329,"source_qid":"3.228"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_