INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('505f7d24d12b38ffc520','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','333','Mixed/Unclassified','Australian Medical Council','{"A":"Reassure the parents.","B":"Monthly monitoring of head circumference.","C":"Brain CT scan.","D":"Brain MRI scan.","E":"Refer to a neurosurgeon.\nMCQ 3.234\nA 6-year-old girl is seen in general practice with her parents. She has had multiple\nepisodes over a three-month period of staring blankly for a few seconds associated\nwith some eyelid fluttering. After each episode she seems normal and continues\nwith the activity in which she was involved. The episodes are now more frequent.\nAn electroencephalogram (EEG) shows 3Hz spike and wave activity. Her parents ask\nabout the prognosis of their daughter’s condition. Which one of the following is the\nmost appropriate advice?\nA. Her episodes are likely to remit spontaneously after two to three years of\nanticonvulsants.\nB. She is highly likely to develop akinetic seizures.\nC. Her episodes are a precursor to juvenile myoclonic epilepsy.\nD. Her episodes are generally resistant to standard anti-epileptic drugs.\nE. She is likely to develop intellectual disability despite seizure control.\nMCQ 3.235\nA 5-year-old girl has had three generalised clonic tonic seizures in the past two months.\nFour weeks ago she was commenced on phenytoin (Dilantin®) working up to 100mg\ntwice daily. She presents now with drowsiness, vomiting and loss of balance. Which\none of the following is the most appropriate next step in management?\nA. Arrange an MRI brain scan.\nB. Give electrolyte replacement solution (e.g. Gastrolyte®)\nC. Arrange an electroencephalogram (EEG).\nD. Add sodium valproate (Epilim®).\nE. Reduce phenytoin dose.\nMCQ 3.236\nA 4-year-old boy presents with the sudden onset of repeated upward rolling of the\neyes, arching of the back and involuntary movements of the limbs. One day previously\nhe had been treated by his local doctor for an acute episode of vomiting and was\ngiven an intramuscular injection to stop his vomiting. Which one of the following is the\nmost likely diagnosis?\nA. Reaction to the prescribed antiemetic.\nB. Paracetamol toxicity.\nC. Epilepsy.\nD. A glioma of the mid-brain.\nE. E. colimeningitis.\n315"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.234","duplicate_group_id":"exact-9a7e35f37905","duplicate_sources":[{"record_id":"505f7d24d12b38ffc520","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":333,"source_qid":"3.234"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','low','{"record_id":"505f7d24d12b38ffc520","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":333,"source_qid":"3.234","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council","options":{"A":"Reassure the parents.","B":"Monthly monitoring of head circumference.","C":"Brain CT scan.","D":"Brain MRI scan.","E":"Refer to a neurosurgeon.\nMCQ 3.234\nA 6-year-old girl is seen in general practice with her parents. She has had multiple\nepisodes over a three-month period of staring blankly for a few seconds associated\nwith some eyelid fluttering. After each episode she seems normal and continues\nwith the activity in which she was involved. The episodes are now more frequent.\nAn electroencephalogram (EEG) shows 3Hz spike and wave activity. Her parents ask\nabout the prognosis of their daughter’s condition. Which one of the following is the\nmost appropriate advice?\nA. Her episodes are likely to remit spontaneously after two to three years of\nanticonvulsants.\nB. She is highly likely to develop akinetic seizures.\nC. Her episodes are a precursor to juvenile myoclonic epilepsy.\nD. Her episodes are generally resistant to standard anti-epileptic drugs.\nE. She is likely to develop intellectual disability despite seizure control.\nMCQ 3.235\nA 5-year-old girl has had three generalised clonic tonic seizures in the past two months.\nFour weeks ago she was commenced on phenytoin (Dilantin®) working up to 100mg\ntwice daily. She presents now with drowsiness, vomiting and loss of balance. Which\none of the following is the most appropriate next step in management?\nA. Arrange an MRI brain scan.\nB. Give electrolyte replacement solution (e.g. Gastrolyte®)\nC. Arrange an electroencephalogram (EEG).\nD. Add sodium valproate (Epilim®).\nE. Reduce phenytoin dose.\nMCQ 3.236\nA 4-year-old boy presents with the sudden onset of repeated upward rolling of the\neyes, arching of the back and involuntary movements of the limbs. One day previously\nhe had been treated by his local doctor for an acute episode of vomiting and was\ngiven an intramuscular injection to stop his vomiting. Which one of the following is the\nmost likely diagnosis?\nA. Reaction to the prescribed antiemetic.\nB. Paracetamol toxicity.\nC. Epilepsy.\nD. A glioma of the mid-brain.\nE. E. colimeningitis.\n315"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_questi