INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9bae4d2f1372f0fd8fa1','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','333','Mixed/Unclassified','Australian Medical Council
A. Reassure the parents.
B. Monthly monitoring of head circumference.
C. Brain CT scan.
D. Brain MRI scan.
E. Refer to a neurosurgeon.
MCQ 3.234
A 6-year-old girl is seen in general practice with her parents. She has had multiple
episodes over a three-month period of staring blankly for a few seconds associated
with some eyelid fluttering. After each episode she seems normal and continues
with the activity in which she was involved. The episodes are now more frequent.
An electroencephalogram (EEG) shows 3Hz spike and wave activity. Her parents ask
about the prognosis of their daughter’s condition. Which one of the following is the
most appropriate advice?
A. Her episodes are likely to remit spontaneously after two to three years of
anticonvulsants.
B. She is highly likely to develop akinetic seizures.
C. Her episodes are a precursor to juvenile myoclonic epilepsy.
D. Her episodes are generally resistant to standard anti-epileptic drugs.
E. She is likely to develop intellectual disability despite seizure control.
MCQ 3.235
A 5-year-old girl has had three generalised clonic tonic seizures in the past two months.
Four weeks ago she was commenced on phenytoin (Dilantin®) working up to 100mg
twice daily. She presents now with drowsiness, vomiting and loss of balance. Which
one of the following is the most appropriate next step in management?','{"A":"Arrange an MRI brain scan.","B":"Give electrolyte replacement solution (e.g. Gastrolyte®)","C":"Arrange an electroencephalogram (EEG).","D":"Add sodium valproate (Epilim®).","E":"Reduce phenytoin dose.\nMCQ 3.236"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[333],"source_qid":"3.234","duplicate_group_id":"exact-1ec2d7e0938d","duplicate_sources":[{"record_id":"9bae4d2f1372f0fd8fa1","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":333,"source_qid":"3.234"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','high','{"record_id":"9bae4d2f1372f0fd8fa1","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":333,"supporting_pages":[333],"source_qid":"3.234","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nA. Reassure the parents.\nB. Monthly monitoring of head circumference.\nC. Brain CT scan.\nD. Brain MRI scan.\nE. Refer to a neurosurgeon.\nMCQ 3.234\nA 6-year-old girl is seen in general practice with her parents. She has had multiple\nepisodes over a three-month period of staring blankly for a few seconds associated\nwith some eyelid fluttering. After each episode she seems normal and continues\nwith the activity in which she was involved. The episodes are now more frequent.\nAn electroencephalogram (EEG) shows 3Hz spike and wave activity. Her parents ask\nabout the prognosis of their daughter’s condition. Which one of the following is the\nmost appropriate advice?\nA. Her episodes are likely to remit spontaneously after two to three years of\nanticonvulsants.\nB. She is highly likely to develop akinetic seizures.\nC. Her episodes are a precursor to juvenile myoclonic epilepsy.\nD. Her episodes are generally resistant to standard anti-epileptic drugs.\nE. She is likely to develop intellectual disability despite seizure control.\nMCQ 3.235\nA 5-year-old girl has had three generalised clonic tonic seizures in the past two months.\nFour weeks ago she was commenced on phenytoin (Dilantin®) working up to 100mg\ntwice daily. She presents now with drowsiness, vomiting and loss of balance. Which\none of the following is the most appropriate next step in management?","options":{"A":"Arrange an MRI brain scan.","B":"Give electrolyte replacement solution (e.g. Gastrolyte®)","C":"Arrange an electroencephalogram (EEG).","D":"Add sodium valproate (Epilim®).","E":"Reduce phenytoin dose.\nMCQ 3.236"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","drug","management"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"1ec2d7e0938d3969c8a700fe8371ee4f7e505b68","duplicate_group_id":"exact-1ec2d7e0938d","duplicate_sources":[{"record_id":"9bae4d2f1372f0fd8fa1","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":333,"source_qid":"3.234"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.sour