INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7d1ede76fa6653c1d014','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','338','Mixed/Unclassified','A 7-year-old girl is brought to a general practice because of bed-weiting. She has
always wet the bed once or twice each night. Her health is otherwise normal. Her
mother was a bed-wetter until ten years of age. Physical examination reveals no
abnormality. Which one of the following is the most appropriate investigation?
Intravenous pyelogram (IVP).
Urine microscopy and culture.
. 24-hour urinary protein.
. Nuclear isotope renal scan.
Abdominal ultrasound.
MOOR >
MCQ 3.248
A 6-month-old baby girl is brought to the Emergency Department at a public hospital
by her 19-year-old mother because the baby cries a lot.
The mother is living with her 20-year-old unemployed boyfriend, who is not the father
of the infant. The baby is cared for by the boyfriend while the mother is at work. The
mother said he is finding this difficult and told her that the baby slipped off the table
yesterday while he was changing her.
On examination the baby has a bruise on the left cheek and a swollen left upper arm,
and cries when the arm is moved. X-ray of the left arm is done and shows a spiral
undisplaced fracture of the upper humerus. Which one of the following is the most
appropriate next step to arrange in management?','{"A":"Immediate hospital admission of the infant.","B":"A visit to the home by the social worker.","C":"Home help by an experienced personal childcare worker.","D":"Attendance of the mother and partner to Infant welfare classes.","E":"Early orthopaedic referral.\n\nMCQ 3.249\n\nA mother brings her 4-year-old daughter to a general practice because of intermittent\nyellow staining on her daughter''s panties. The child is well, and the vulva appears\nnormal apart from some redness seen in the region of the inner aspect of the labia.\nWhich one of the following is the most likely cause for the child''s symptoms?\n\n. Asexually transmitted infection.\nA vaginal foreign body.\n\n. Nonspecific vulvovaginitis.\n\n. Candida vaginitis.\nGardnerella vaginitis.\n\nMm O Q2o5 &"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.247","duplicate_group_id":"exact-63ec151595a2","duplicate_sources":[{"record_id":"7d1ede76fa6653c1d014","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":338,"source_qid":"3.247"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"7d1ede76fa6653c1d014","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":338,"source_qid":"3.247","domain_hint":"Mixed/Unclassified","stem":"A 7-year-old girl is brought to a general practice because of bed-weiting. She has\nalways wet the bed once or twice each night. Her health is otherwise normal