INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ae2ac361bc9e72b77c5d','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','339','Mixed/Unclassified',': Australian Medical Council
| MCQ 3.250
3 Pubertal events normally take place in a sequential manner. Knowledge of this
f will assist the clinician in defining the likely cause of any pubertal development
) abnormality which occurs and in answering parental concerns. Which one of the
following progression of events in girls is correct?
A. Breast budding; pubic and axillary hair; acceleration of growth.
B. Acceleration of growth; breast budding; pubic and axillary hair.
C. Breast budding; acceleration of growth; pubic and axillary hair.
D. Pubic and axillary hair; acceleration of growth; breast budding.
E. Acceleration of growth; pubic and axillary hair; breast budding.
MCQ 3.251
| A 2-year-old boy who attends day care four days a week is brought to see you as his
mother is worried about his poor appetite, frequent upper respiratory infections and
, poor energy levels.
Physical examination reveals no abnormality. He is on the 25th percentile for height,
; weight, and head circumference.
Investigations show:
| Haemoglobin (Hb) 143g/L (130-180)
t White cell count (WCC) 5.5x10°/L (4-11)
Serum sodium 143mmol/L (135-145)
Serum potassium 4.Ammol/L (3.5-4.9)
Serum chloride 107mmol/L (95-110)
Blood glucose 5.8mmol/L (3-7.7)
Liver function tests normal
. Serum iron *5umol/L (10-33)
Serum ferritin Alumol/L (6-60)
t Which one of the following would be the most appropriate management?','{"A":"Remove from day care.","B":"Reassure.","C":"Refer to an immunologist.","D":"Commence iron supplements.","E":"Coeliac disease serology.\nMCQ 3.252"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[339],"source_qid":"3.250","duplicate_group_id":"exact-6e451819a280","duplicate_sources":[{"record_id":"ae2ac361bc9e72b77c5d","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":339,"source_qid":"3.250"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"ae2ac361bc9e72b77c5d","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":339,"supporting_pages":[339],"source_qid":"3.250","domain_hint":"Mixed/Unclassified","stem":": Australian Medical Council\n| MCQ 3.250\n3 Pubertal events normally take place in a sequential manner. Knowledge of this\nf will assist the clinician in defining the likely cause of any pubertal development\n) abnormality which occurs and in answering parental concerns. Which one of the\nfollowing progression of events in girls is correct?\nA. Breast budding; pubic and axillary hair; acceleration of growth.\nB. Acceleration of growth; breast budding; pubic and axillary hair.\nC. Breast budding; acceleration of growth; pubic and axillary hair.\nD. Pubic and axillary hair; acceleration of growth; breast budding.\nE. Acceleration of growth; pubic and axillary hair; breast bu