INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1ad18aa061b0e1930b76','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','340','Mixed/Unclassified','A baby is born to a woman who has previously been healthy except for mild
hypertension. She has had two previous children and had spontaneous rupture of
membranes and onset of labour at term. She received pain relief with an intramuscular
injection of 10mg morphine two hours before the delivery. After an uncomplicated
vacuum delivery the baby is slow to breathe with an Apgar score of 4 at 1 minute.
Which one of the following is the most important next step in the baby’s care?','{"A":"Intramuscular naloxone.","B":"Oxygen by nasal catheter.","C":"Umbilical venous 8.4% sodium bicarbonate.","D":"Bag and mask ventilation.","E":"Intubation.\n\nMCQ 3.255\n\nA3-year-old boy is admitted with a one-week history of increasing generalised swelling\nand periorbital puffiness following a respiratory infection two weeks previously. On\nexamination, he has generalised oedema, with ascites and marked scrotal oedema.\nHe is normotensive.\n\nUrine testing shows 4+ protein, there is no glycosuria or haematuria. Which one of the\nfollowing is the most likely cause for his presentation?\n\nIgA nephropathy.\n\nAcute glomerulonephritis.\n\n. Reflux nephropathy.\n\nInterstitial nephritis.\n\nNephrotic syndrome.\n\nMOOR>"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[340],"source_qid":"3.253","duplicate_group_id":"exact-e3bb1e1c0588","duplicate_sources":[{"record_id":"1ad18aa061b0e1930b76","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":340,"source_qid":"3.253"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_multi_question_group","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"1ad18aa061b0e1930b76","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":340,"supporting_pages":[340],"source_qid":"3.253","domain_hint":"Mixed/Unclassified","stem":"A baby is born to a woman who has previously been healthy except for mild\nhypertension. She has had two previous children and had spontaneous rupture of\nmembranes and onset of labour at term. She received pain relief with an intramuscular\ninjection of 10mg morphine two hours before the delivery. After an uncomplicated\nvacuum delivery the baby is slow to breathe with an Apgar score of 4 at 1 minute.\nWhich one of the following is the most important next step in the baby’s care?","options":{"A":"Intramuscular naloxone.","B":"Oxygen by nasal catheter.","C":"Umbilical venous 8.4% sodium bicarbonate.","D":"Bag and mask ventilation.","E":"Intubation.\n\nMCQ 3.255\n\nA3-year-old boy is admitted with a one-week history of increasing generalised swelling\nand periorbital puffiness following a respiratory infection two weeks previously. On\nexamination, he has generalised oedema, with ascites and marked scrotal oedema.\nHe is normotensive.\n\nUrine testing shows 4+ protein, there is no glycosuria or haematuria. Which one of the\nfollowing is the most likely cause for his presentation?\n\nIgA nephropathy.\n\nAcute glomerulonephritis.\n\n. Reflux nephropathy.\n\nInterstitial nephritis.\n\nNephrotic syndrome.\n\nMOOR>"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["hypertension"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"v28_multi_question_group","text_method":"tesseract","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"e3bb1e1c058894ddf88fe5d7f58a85b02be4d7f1","duplicate_group_id":"exact-e3bb1e1c0588","duplicate_sources":[{"record_id":"1ad18aa061b0e1930b76","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":340,"source_qid":"3.253"}]}',0,'v2.9.4','2026-09-24T0