INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1baf605aabd0683c2f2a','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','343','Mixed/Unclassified','Australian Medical Council
) MCQ 3.262
A mother presents with her 2-year-old son complaining that his appetite is poor.
On questioning, she says that he is very well with no past history of illness and
he has plenty of energy. His general development is normal and he has had
no vomiting or diarrhoea but the single bowel motion he passes each day is
loose. Which one of the following would be the most appropriate next step in
management?','{"A":"Arrange a stool specimen to exclude giardiasis.","B":"Plot his current height and weight on percentile charts.","C":"Suggest that he remain at table until the food served is eaten.","D":"Prescribe a small dose of iron mixture as an appetite stimulant.","E":"Suggest that he be given just the food that the mother knows he enjoys.\nMCQ 3.263\nA 3-year-old boy is seen in general practice. For the previous two days he has had\n\n‘ bruising over his trunk and limbs and a fine petechial rash over his body. On the\nmorning of presentation he had a nose bleed which lasted for 20 minutes. He had a\nrunny nose two weeks ago but this has resolved completely.\n\n. On examination he looks well and is in no distress. He is afebrile. He has no\nlymphadenopathy nor hepatosplenomegaly. He has fine nonblanching petechiae\nover his trunk and legs and recent bruises on his body. Which one of the following is\nthe most likely diagnosis?\n\nA. Haemophilia A.\n\nB. Von Willebrand disease.\n\nC. Henoch-Sch6nlein purpura.\n\nD. Acute lymphoblastic leukaemia.\n\n= E. Immune thrombocytopenia.\n\n5 MCQ 3.264\n\n: A 10-month-old girl is seen with a three-day history of low grade fever, irritability\n\nf and poor appetite, although she continues to take fluids well. She has had no\n\n. vomiting or diarrhoea. Her parents have noted that her urine output is reduced and\n\n° her urine is dark with a strong odour. When seen she is alert, is afebrile and has no\nrash. Her urine on testing shows white cells +, protein +, no blood and is negative\nfor nitrites. Which one of the following is the most appropriate next step in her\nmanagement?\n\nA. Blood cultures.\nB. Liver function studies.\nC. A clean catch urine specimen for culture.\nD. A course of trimethoprim.\nE. Advise her parents that the dipstick test excludes a urinary tract infection (UTI).\n| 325"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.262","duplicate_group_id":"exact-85fcd0267e2f","duplicate_sources":[{"record_id":"1baf605aabd0683c2f2a","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":343,"source_qid":"3.262"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"1baf605aabd0683c2f2a","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":343,"source_qid":"3.262","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\n) MCQ 3.262\nA mother presents with her 2-year-old son complaining that his appetite is poor.\nOn questioning, she says that he is very well with no past history of illness and\nhe has plenty of energy. His general development is normal and he has had\nno vomiting or diarrhoea but the single bowel motion he passes each day is\nloose. Which one of the following would be the most appropriate next step in\nmanagement?","options":{"A":"Arrange a stool specimen to exclude giardiasis.","B":"Plot his current height and weight on percentile charts.","C":"Suggest that he remain at table until the food served is eaten.","D":"Prescribe a small dose of iron mixture as an appetite stimulant.","E":"Suggest that he be given just the food that the mother knows he enjoys.\nMCQ 3.263\nA 3-year-old boy is seen in general practice. For the previous two days he has had\n\n‘ bruising over his trunk and limbs and a fine petechial rash over his body. On the\nmorning of presentation he had a nose bleed which lasted for 20 minutes. He had a\nrunny nose two weeks ago but this has resolved completely.\n\n. On examination he looks well and is in no distress. He is afebrile. He has no\nlymphadenopathy nor hepatosplenomegaly. He has fine nonblanching petechiae\nover his trunk and legs and recent bruises on his body. Which one of the following is\nthe most likely diagnosis?\n\nA. Haemophilia A.\n\nB. Von Willebrand disease.\n\nC. Henoch-Sch6nlein purpura.\n\nD. Acute lymphoblastic leukaemia.\n\n= E. Immune thrombocytopenia.\n\n5 MCQ 3.264\n\n: A 10-month-old girl is seen with a three-day history of low grade fever, irritability\n\nf and poor appetite, although she continues to take fluids well. She has had no\n\n. vomiting or diarrhoea. Her parents have noted that her urine output is reduced and\n\n° her urine is dark with a strong odour. When seen she is alert, is afebrile and has no\nrash. Her urine on testing shows white cells +, protein +, no blood and is negative\nfor nitrites. Which one of the following is the most appropriate next step in her\nmanagement?\n\nA. Blood cultures.\nB. Liver function studies.\nC. A clean catch urine specimen for culture.\nD. A course of trimethoprim.\nE. Advise her parents that the dipstick test excludes a urinary tract infection (UTI).\n| 325"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","record_type":"text_mcq","options_mode":"text","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"85fcd0267e2f143ba4038158fdf3b0e0da087202","duplicate_group_id":"exact-85fcd0267e2f","duplicate_sources":[{"record_id":"1baf605aabd0683c2f2a","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":343,"source_qid":"3.262"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
