INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('e063d50afe8988da0b91','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','345','Mixed/Unclassified','Australian Medical Council
A. Commence sodium valproate.
B. Arrange a sleep electroencephalogram (EEG).
C. Suggest restriction of his evening television viewing.
D. Reassure that these episodes should settle spontaneously.
E. Advise that these episodes are secondary to stresses during the previous day.
MCQ 3.268
A 5-year-old girl was found to have a cardiac bruit wnen she presented with an
upper respiratory tract infection. When reviewed the following week, the murmur is
still present and is grade 2-3/5, mid-systolic in timing, maximal at the left upper sternal
edge. Which one of the following associated features would suggest that her murmur
is most likely of an organic origin warranting investigation?
A. Her infant brother has Down syndrome.
B. A mid-diastolic murmur is also present.
C. Her pulse rate increases when she takes a deep breath.
D. Her hands and toes go blue after she has been swimming.
E. She has had five upper respiratory infections in her first year at school/
; kindergarten.
MCQ 3.269
A 5-year-old boy presents because of intermittent attacks of wheezing which
have occurred 2-3 times a year over the last two years. These episodes are usually
precipitated by viral respiratory illnesses and last for 1-2 days. They respond to
: symptomatic treatment of his respiratory illness with inhaled salbutamol. In between
| episodes he is well with no interval symptoms.
His older sibling had flexural eczema until the age of 18 months. Which one of the
following would be the most appropriate management?','{"A":"Inhaled sodium cromoglycate.","B":"Inhaled fluticasone.","C":"Inhaled salbutamol when symptomatic.","D":"Oral monteleukast.","E":"Oral prednisolone when symptomatic."}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[345],"source_qid":"3.268","duplicate_group_id":"exact-28da71260992","duplicate_sources":[{"record_id":"e063d50afe8988da0b91","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":345,"source_qid":"3.268"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_multi_group","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','high','{"record_id":"e063d50afe8988da0b91","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":345,"supporting_pages":[345],"source_qid":"3.268","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nA. Commence sodium valproate.\nB. Arrange a sleep electroencephalogram (EEG).\nC. Suggest restriction of his evening television viewing.\nD. Reassure that these episodes should settle spontaneously.\nE. Advise that these episodes are secondary to stresses during the previous day.\nMCQ 3.268\nA 5-year-old girl was found to have a cardiac bruit wnen she presented with an\nupper respiratory tract infection. When reviewed the following week, the murmur is\nstill present and is grade 2-3/5, mid-systolic in timing, maximal at the left upper sternal\nedge. Which one of the following associated features would suggest that her murmur\nis most likely of an 