INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4a25007add3911b0eac9','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','347','Mixed/Unclassified','Australian Medical Council
MCQ 3.274
A 6-year-old girl presents with her third episode of pallor and mildly icteric sclerae
associated with symptoms of a mild upper respiratory tract infection. On examination,
she has an easily tipped spleen. Which one of the following investigations is most likely to
. confirm her diagnosis?','{"A":"Coombs test.","B":"Reticulocyte count.","C":"Eosin-5-maleimide (E5M) staining test.","D":"Haemoglobin electrophoresis.","E":"Howell-Jolly bodies in a red blood cell smear.\n\nMCQ 3.275\n\nA 7-year-old boy presents with a history of a painful left leg for two days and a fever\nfor the past 36 hours.\n\n} On examination, he has an infected skin lesion on the dorsum of his left foot which\nis exuding pus. The rest of his foot is swollen, red and tender and he has red streaks\ngoing up the inside of his leg. He limps on walking.\n\n1 On examination of his groin he has enlarged tender lymph nodes. His temperature is\n\n: 39°C. Which one of the following antibiotic regimens would be the most appropriate\ninitial therapy?\n\nA. Oral cefaclor.\n\nB. Intravenous amoxycillin and gentamicin.\nC. Intravenous flucloxacillin.\n\nD. Oral norfloxacin.\n\nE. Oral roxithromycin.\n\nMCQ 3.276\n\n) A 6-year-old boy presents with a six-week history of increasing headache and morning\n\ni ataxia. He has no fever. A computed tomograph (CT) brain scan shows a midline\n\n> cerebellar mass. Which one of the following is the most likely diagnosis?\n\n: A. Neurofibroma.\n\nB. Meningioma.\nC. Medulloblastoma.\nD. Cerebellar abscess.\nE. Glioblastoma multiforme.\nMCQ 3.277\nA 5-year-old boy is presented as his parents have noted several episodes of vacant\nstaring associated with fluttering of his eye lids. These episodes last approximately 20\nseconds and have occurred over the last three months. Which one of the following is\nthe most likely diagnosis?\n\n\\ 329"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.274","duplicate_group_id":"exact-3b5e05e9824b","duplicate_sources":[{"record_id":"4a25007add3911b0eac9","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":347,"source_qid":"3.274"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','low','{"record_id":"4a25007add3911b0eac9","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":347,"source_qid":"3.274","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nMCQ 3.274\nA 6-year-old girl presents with her third episode of pallor and mildly icteric sclerae\nassociated with symptoms of a mild upper respiratory tract infection. On examination,\nshe has an easily tipped spleen. Which one of the following investigations is most likely to\n. confirm her diagnosis?","options":{"A":"Coombs test.","B":"Reticulocyte count.","C":"Eosin-5-maleimide (E5M) staining test.","D":"Haemoglobin electrophoresis.","E":"Howell-Jolly bodies in a red blood cell smear.\n\nMCQ 3.275\n\nA 7-year-old boy presents with a history of a painful left leg for two days and a fever\nfor the past 36 hours.\n\n} On examination, he has an infected skin lesion on the dorsum of his left foot which\nis exuding pus. The rest of his foot is swollen, red and tender and he has red streaks\ngoing up the inside of his leg. He limps on walking.\n\n1 On examination of his groin he has enlarged tender lymph nodes. His temperature is\n\n: 39°C. Which one of the following antibiotic regimens would be the most appropriate\ninitial therapy?\n\nA. Oral cefaclor.\n\nB. Intravenous amoxycillin and gentamicin.\nC. Intravenous flucloxacillin.\n\nD. Oral norfloxacin.\n\nE. Oral roxithromycin.\n\nMCQ 3.276\n\n) A 6-year-old boy presents with a six-week history of increasing headache and morning\n\ni ataxia. He has no fever. A computed tomograph (CT) brain scan shows a midline\n\n> cerebellar mass. Which one of the following is the most likely diagnosis?\n\n: A. Neurofibroma.\n\nB. Meningioma.\nC. Medulloblastoma.\nD. Cerebellar abscess.\nE. Glioblastoma multiforme.\nMCQ 3.277\nA 5-year-old boy is presented as his parents have noted several episodes of vacant\nstaring associated with fluttering of his eye lids. These episodes last approximately 20\nseconds and have occurred over the last three months. Which one of the following is\nthe most likely diagnosis?\n\n\\ 329"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","record_type":"text_mcq","options_mode":"text","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"3b5e05e9824bab93ee4f87e0c71c13075d3fc440","duplicate_group_id":"exact-3b5e05e9824b","duplicate_sources":[{"record_id":"4a25007add3911b0eac9","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":347,"source_qid":"3.274"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_eviden