INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d0edff89d36c4bf330bc','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','351','Mixed/Unclassified','eae: a Australian Medical Council','{"A":"Her mother has a past history of vesicoureteric reflux (VUR).","B":"Her 6-year-old brother had a urinary tract infection (UTI) when he was aged two\nyears.","C":"An ultrasound during her mother’s pregnancy with her showed mild fetal\n| pelvicalyceal distension.","D":"She had an upper respiratory tract infection three weeks previously.","E":"Her cousin has adult type polycystic kidney disease.\nMCQ 3.287\nA 13-month-old infant is seen in the Emergency Department as he has been unwell for\neight hours with fever, poor feeding and lethargy. His immunisations are up to date.\nOn examination his temperature is 38.7°C and there is a purpuric rash on the trunk\nwith no other focal signs. Which one of the following is the most appropriate initial\ninvestigation?\nA. Lumbar puncture.\nB. Blood culture.\nC. Platelet count.\n. D. Prothrombin time.\nE. Antistreptolysin titre.\nMCQ 3.288\nA child at the age of two years is Usually able to peform which one of the following\ntasks2\nA. Build a tower of two or three blocks\nB. Button his shirt.\nC. Count to five.\nD. Name a colour.\nE. Control the bladder day and night.\nMCQ 3.289\nA 7-year-old girl was a backseat passenger in a car involved in a high-speed head-on\ncollision. She was wearing a two-point seatbelt at the time of the collision. In the\nEmergency Depariment she complains of abdominal pain. Her Glasgow Coma Scale\nscore is 15. Her heart rate is 120/min and her BP is 110/65mmHg. She has a seatbelt\ncontusion across her abdomen below the level of the umbilicus. Her abdomen is\ndistended and tender. Abdominal X-rays show gas above the liver. Which one of the\nfollowing is the most likely source of the gas?\nA. Intestinal perforation\nB. Air tracking from the mediastinum\nC. Diaphragmatic injury\nD. Bladder rupture\nE. Pneumatosis intestinalis.\n333"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.287","duplicate_group_id":"exact-9c3f001c0a57","duplicate_sources":[{"record_id":"d0edff89d36c4bf330bc","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":351,"source_qid":"3.287"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','low','{"record_id":"d0edff89d36c4bf330bc","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":351,"source_qid":"3.287","domain_hint":"Mixed/Unclassified","stem":"eae: a Australian Medical Council","options":{"A":"Her mother has a past history of vesicoureteric reflux (VUR).","B":"Her 6-year-old brother had a urinary tract infection (UTI) when he was aged two\nyears.","C":"An ultrasound during her mother’s pregnancy with her showed mild fetal\n| pelvicalyceal distension.","D":"She had an upper respiratory tract infection three weeks previously.","E":"Her cousin has adult type polycystic kidney disease.\nMCQ 3.287\nA 13-month-old infant is seen in the Emergency Department as he has been unwell for\neight hours with fever, poor feeding and lethargy. His immunisations are up to date.\nOn examination his temperature is 38.7°C and there is a purpuric rash on the trunk\nwith no other focal signs. Which one of the following is the most appropriate initial\ninvestigation?\nA. Lumbar puncture.\nB. Blood culture.\nC. Platelet count.\n. D. Prothrombin time.\nE. Antistreptolysin titre.\nMCQ 3.288\nA child at the age of two years is Usually able to peform which one of the following\ntasks2\nA. Build a tower of two or three blocks\nB. Button his shirt.\nC. Count to five.\nD. Name a colour.\nE. Control the bladder day and night.\nMCQ 3.289\nA 7-year-old girl was a backseat passenger in a car involved in a high-speed head-on\ncollision. She was wearing a two-point seatbelt at the time of the collision. In the\nEmergency Depariment she complains of abdominal pain. Her Glasgow Coma Scale\nscore is 15. Her heart rate is 120/min and her BP is 110/65mmHg. She has a seatbelt\ncontusion across her abdomen below the level of the umbilicus. Her abdomen is\ndistended and tender. Abdominal X-rays show gas above the liver. Which one of the\nfollowing is the most likely source of the gas?\nA. Intestinal perforation\nB. Air tracking from the mediastinum\nC. Diaphragmatic injury\nD. Bladder rupture\nE. Pneumatosis intestinalis.\n333"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","record_type":"text_mcq","options_mode":"text","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"9c3f001c0a57eaa6d1c9df5aa7a87bfed8c7866d","duplicate_group_id":"exact-9c3f001c0a57","duplicate_sources":[{"record_id":"d0edff89d36c4bf330bc","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":351,"source_qid":"3.287"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
