INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d2a6c02f421a0e7994f4','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','352','Mixed/Unclassified','Australian Medical Council 4
| a 3
| MCQ 3.290 }
A 13-year-old boy presents with a three-week history of intermittent pain in his right leg
causing him to limp. He is a keen soccer player of average ability and is significantly
overweight. When asked to indicate the site of pain he points to his right knee. He is
afebrile and his right knee is normal on clinical examination. Examination of his right |
hip shows limitation of internal rotation due to pain. Which one of the following is the
: most likely diagnosis? q','{"A":"Perthes disease.","B":"Transient synovitis of the hip.","C":"Septic arthritis of the hip.","D":"Slipped capital femoral epiphysis.","E":"Osteosarcoma of upper femur.\nSt eeosesneestsssstesenensnees\nMCQ 3.291\nA couple present their baby aged four weeks with the complaint that he has vomiting\n§ which started at two weeks of age. It has become more severe in the last three days,\n} occurring after every feed. They describe the vomiting as being quite forceful and\n? he has lost 300g weight in the last two days. The vomitus contains the milk that had if\nbeen taken in the previous feed and the baby is continually hungry. His urine output\nin the last 24 hours has reduced. On examination he is active and crying and looks a\nlittle scrawny and mildly dehydrated. Examination of his abdomen is difficult as he is\ncrying, but appears normal. Which one of the following is the most likely cause of his\nvomiting?\nA. Gastro-oesophagedl reflux.\nB. Malrotation of the gut.\nC. Congenital adrenal hyperplasia.\nD. Hypertrophic pyloric stenosis.\nE. Urinary tract infection.\ni seseusnsesceosssnsesenssnenennsn\nMCQ 3.292\nA couple present with their 4-week-old baby with the complaint that he has been\nvomiting, which started at two weeks of age. It has become more severe in the last |\nthree days, occurring after every feed. They describe the vomiting as being quite\nforceful and he has lost 300g in weight in the last two days. The vomitus contains the\nmilk that had been taken in the previous feed and the baby is continually hungry.\nHis urine output in the last 24 hours has become less than previously noted. On\nexamination he is active and crying and looks a little scrawny and mildly dehydrated.\nExamination of his abdomen is difficult as he is crying, but appears normal. Which one\nof the following would be the most appropriate next step in assessing this infant?\nA. Arrange estimation of serum electrolytes.\nB. Abdominal palpation during a test feed.\nC. Arrange a barium swallow.\nD. Perform a suprapubic aspiration of his bladder.\nE. Arrange for flat and erect abdomen X-rays.\n|\n334 ''b"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.290","duplicate_group_id":"exact-5ebde9e6f071","duplicate_sources":[{"record_id":"d2a6c02f421a0e7994f4","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":352,"source_qid":"3.290"}],"parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','medium','{"record_id":"d2a6c02f421a0e7994f4","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":352,"source_qid":"3.290","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council 4\n| a 3\n| MCQ 3.290 }\nA 13-year-old boy presents with a three-week history of intermittent pain in his right leg\ncausing him to limp. He is a keen soccer player of average ability and is significantly\noverweight. When asked to indicate the site of pain he points to his right knee. He is\nafebrile and his right knee is normal on clinical examination. Examination of his right |\nhip shows limitation of internal rotation due to pain. Which one of the following is the\n: most likely diagnosis? q","options":{"A":"Perthes disease.","B":"Transient synovitis of the hip.","C":"Septic arthritis of the hip.","D":"Slipped capital femoral epiphysis.","E":"Osteosarcoma of upper femur.\nSt eeosesneestsssstesenensnees\nMCQ 3.291\nA couple present their baby aged four weeks with the 