INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('17a8e8dcffe0ca58c988','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','353','Mixed/Unclassified','i
Australian Medical Council
Section 3 = Child and Adolescent Health.
MCQ 3.293
A 3-year-old boy is seen in general practice. For the previous two days he has had
bruising over his trunk and limbs and a fine petechial rash over his body. On the
morning of presentation he had a nose bleed which lasted for 20 minutes.
On examination he looks well and is in no distress. He is afebrile. He has no
lymphadenopathy nor hepatosplenomegaly. He has fine nonblanching petechiae
over his trunk and legs and recent bruises on his body. Which one of the following
aspects of his medical history would be most helpful in making a diagnosis?','{"A":"He has a first cousin with haemophilia A.","B":"His mother has systemic lupus erythematosus.","C":"At 18 months of age he had a mild nutritional iron deficiency anaemia treated\nwith oral iron.","D":"Ten days previously he had a viral upper respiratory infection which persisted for\nthree days.","E":"The family is suffering significant financial hardship.\n\nMCQ 3.294\n\nA 10-month-old infant is brought into the Emergency Department by her mother.\nShe has been unwell for three days with rhinorrhoea followed by cough and mild\nfevers. Her condition has worsened over the last 24 hours and she is now feeding\npoorly. On examination she is afebrile, listless and has tachypnoea, tracheal tug,\nintercostal recession and nasal flaring. On auscultation there are widespread bilateral\ncrepitations and an expiratory wheeze. Which one of the following is the most likely\ncourse of her illness?\n\nA. Resolution in 2-3 days.\n\nB. Improvement in 7-10 days.\n\nC. Rapid improvement with intravenous antibiotics.\nD. Persistent cough for at least 6 months.\n\nE. Chronic lung disease.\n\nMCQ 3.295\n\nAn 18-month-old girl is brought to the Emergency Department by her mother. The\nchild has been vomiting for 24 hours and has had several loose stools. Her mother says\nher child has felt hot and over the last six hours has been irritable and lethargic. On\nexamination she is lying quietly in her mother''s arms and her temperature is 37.8°C,\npulse 110/min, respiratory rate 30/min, weight 15kg and her capillary return is three\nseconds. She has a dry mouth, sunken eyes and reduced skin turgor. Which one of the\nfollowing would be the most appropriate volume to be used for an initial intravenous\nbolus over fifteen minutes?\n\n100mL.\n300mL.\n. 500mL.\n700mL.\n900mL.\n\nMOQRP>"}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.293","duplicate_group_id":"exact-d72613578b13","duplicate_sources":[{"record_id":"17a8e8dcffe0ca58c988","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":353,"source_qid":"3.293"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"17a8e8dcffe0ca58c988","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":353,"source_qid":"3.293","domain_hint":"Mixed/Unclassified","stem":"i\nAustralian Medical Council\nSection 3 = Child and Adolescent Health.\nMCQ 3.293\nA 3-year-old boy is seen in general practice. For the previous two days he has had\nbruising over his trunk and limbs and a fine petechial rash over his body. On the\nmorning of presentation he had a nose bleed which lasted for 20 minutes.\nOn examination he looks well and is in no distress. He is afebrile. He has no\nlymphadenopathy nor hepatosplenomegaly. He has fine nonblanching petechiae\nover his trunk and legs and recent bruises on his body. Which one of the following\naspects of his medical history would be most helpful in making a diagnosis?","options":{"A":"He has a first cousin with haemophilia A.","B":"His mother has systemic lupus erythematosus.","C":"At 18 months of age he had a mild nutritional iron deficiency anaemia treated\nwith oral iron.","D":"Ten days previously he had a viral upper respiratory infection which persisted for\nthree days.","E":"The family is suffering significant financial hardship.\n\nMCQ 3.294\n\nA 10-month-old infant is brought into the Emergency Department by her mother.\nShe has been unwell for three days with rhinorrhoea followed by cough and mild\nfevers. Her condition has worsened over the last 24 hours and she is now feeding\npoorly. On examination she is afebrile, listless and has tachypnoea, tracheal tug,\nintercostal recession and nasal flaring. On auscultation there are widespread bilateral\ncrepitations and an expiratory wheeze. Which one of the following is the most likely\ncourse of her illness?\n\nA. Resolution in 2-3 days.\n\nB. Improvement in 7-10 days.\n\nC. Rapid improvement with intravenous antibiotics.\nD. Persistent cough for at least 6 months.\n\nE. Chronic lung disease.\n\nMCQ 3.295\n\nAn 18-month-old girl is brought to the Emergency Department by her mother. The\nchild has been vomiting for 24 hours and has had several loose stools. Her mother says\nher child has felt hot and over the last six hours has been irritable and lethargic. On\nexamination she is lying quietly in her mother''s arms and her temperature is 37.8°C,\npulse 110/min, respiratory rate 30/min, weight 15kg and her capillary return is three\nseconds. She has a dry mouth, sunken eyes and reduced skin turgor. Which one of the\nfollowing would be the most appropriate volume to be used for an initial intravenous\nbolus over fifteen minutes?\n\n100mL.\n300mL.\n. 500mL.\n700mL.\n900mL.\n\nMOQRP>"},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"d72613578b13c9c200df1180450f53c85ac19467","duplicate_group_id":"exact-d72613578b13","duplicate_sources":[{"record_id":"17a8e8dcffe0ca58c988","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf",