ritional iron deficiency anaemia treated\nwith oral iron.","D":"Ten days previously he had a viral upper respiratory infection which persisted for\nthree days.","E":"The family is suffering significant financial hardship.\n\nMCQ 3.294"},"options_mode":"text","source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"v28_multi_question_group","text_method":"tesseract","parser_version":"2.8-residual-resolver-selective-ocr-visual-2026-09-22","stem_hash":"d440d066f090c5f2fc7d52ca63fd2dc09cce41fd","duplicate_group_id":"exact-d440d066f090","duplicate_sources":[{"record_id":"4dda458d8734ef1a171f","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":353,"source_qid":"3.293"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
