INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('331aab8f08e0600aa6d3','96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf','356','Mixed/Unclassified','Australian Medical Council
Section 3 — Maternal! Health
a
MCQ 3.299
A 14-year-old girl presents to your clinic because she is requesting termination of
her pregnancy (TOP) which is at 10 weeks of gestation. She has been living with her
21-year-old boyfriend for the last 12 months, but against her parent''s wishes, however
he has deserted her on learning she is pregnant. Which one of the following would be
the most appropriate next step in her care?','{"A":"Refer her for pregnancy termination based on her own informed consent. |","B":"Get parental consent for termination of pregnancy.","C":"Contact the police as the sexual relationship was illegal in view of the age\n\ndifference.","D":"Contact the Child Protection Authority.","E":"Refuse her request on the grounds of age.\nH i| ee eeeseneeneenssenenssneesntnstietennenunenesnnaceneensnnnnt\niil MCQ 3.300\n\n} A patient, who has had three successive spontaneous abortions, attends at 12 weeks\nof gestation in her fourth pregnancy. Her menstrual cycles have been regular and\ni of 28 days duration. Just prior to presenting for assessment she passed a moderate\namount of blood with clots per vaginam and had some intermittent lower abdominal\npain. On vaginal examination, the cervical canal admitted one finger readily and\n||} bimanual palpation showed a uterus compatible in size with a pregnancy of only\n| 8 weeks duration. Which one of the following is the most appropriate next step in\ni | management?\n\ni\n\ni\n\nH\n\nij\n\n. Pregnancy test.\nSerum beta-hCG level.\n. Curettage.\n\nVaginal ultrasound.\nCervical ligation.\n\nMOQ2P>\n\nMCQ 3.301\n\nA 25-year-old woman, who lives 50km from the nearest tertiary referral obstetric\nhospital, presents because of premature rupture of her membranes (PROM) at 26\nweeks of gestation, two days ago. This is her first pregnancy andithad been progressing\nnormally until the time the membranes ruptured. No contractions have occurred in\nthe last 48 hours, she has been transferred to the tertiary referral obstetric hospital,\nglucocorticoid therapy has been given, cervical swabs collected, prophylactic\niit antibiotics commenced and ultrasound and cardiotocograph (CTG) assessments\nmade. The cervical swabs showed growth of normal vaginal flora only, the ultrasound\nshowed almost no liquor was present, and the CTG was normal and reactive. Which\none of the following options is most appropriate regarding her subsequent care?\n\nA. Prophylactic antibiotic therapy should be continued uniil delivery occurs.\n\nB. Contraction-inhibiting drugs should be administered from now until established\nlabour occurs.\n\nC. CIG assessments of the fetal heart rate should be repeated weekly.\n\nD. The white cell count (WCC) and C-reactive protein (CRP) levels should be assessed\nevery 2-3 days.\nE. Labour should be induced now."}',NULL,NULL,'{"source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","supporting_pages":[],"source_qid":"3.299","duplicate_group_id":"exact-f0a5bd6458ee","duplicate_sources":[{"record_id":"331aab8f08e0600aa6d3","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":356,"source_qid":"3.299"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"331aab8f08e0600aa6d3","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_year":null,"source_page":356,"source_qid":"3.299","domain_hint":"Mixed/Unclassified","stem":"Australian Medical Council\nSection 3 — Maternal! Health\na\nMCQ 3.299\nA 14-year-old girl presents to your clinic because she is requesting termination of\nher pregnancy (TOP) which is at 10 weeks of gestation. She has been living with her\n21-year-old boyfriend for the last 12 months, but against her parent''s wishes, however\nhe has deserted her on learning she is pregnant. Which one of the following would be\nthe most appropriate next step in her care?","options":{"A":"Refer her for pregnancy termination based on her own informed consent. |","B":"Get parental consent for termination of pregnancy.","C":"Contact the police as the sexual relationship was illegal in view of the age\n\ndifference.","D":"Contact the Child Protection Authority.","E":"Refuse her request on the grounds of age.\nH i| ee eeeseneeneenssenenssneesntnstietennenunenesnnaceneensnnnnt\niil MCQ 3.300\n\n} A patient, who has had three successive spontaneous abortions, attends at 12 weeks\nof gestation in her fourth pregnancy. Her menstrual cycles have been regular and\ni of 28 days duration. Just prior to presenting for assessment she passed a moderate\namount of blood with clots per vaginam and had some intermittent lower abdominal\npain. On vaginal examination, the cervical canal admitted one finger readily and\n||} bimanual palpation showed a uterus compatible in size with a pregnancy of only\n| 8 weeks duration. Which one of the following is the most appropriate next step in\ni | management?\n\ni\n\ni\n\nH\n\nij\n\n. Pregnancy test.\nSerum beta-hCG level.\n. Curettage.\n\nVaginal ultrasound.\nCervical ligation.\n\nMOQ2P>\n\nMCQ 3.301\n\nA 25-year-old woman, who lives 50km from the nearest tertiary referral obstetric\nhospital, presents because of premature rupture of her membranes (PROM) at 26\nweeks of gestation, two days ago. This is her first pregnancy andithad been progressing\nnormally until the time the membranes ruptured. No contractions have occurred in\nthe last 48 hours, she has been transferred to the tertiary referral obstetric hospital,\nglucocorticoid therapy has been given, cervical swabs collected, prophylactic\niit antibiotics commenced and ultrasound and cardiotocograph (CTG) assessments\nmade. The cervical swabs showed growth of normal vaginal flora only, the ultrasound\nshowed almost no liquor was present, and the CTG was normal and reactive. Which\none of the following options is most appropriate regarding her subsequent care?\n\nA. Prophylactic antibiotic therapy should be continued uniil delivery occurs.\n\nB. Contraction-inhibiting drugs should be administered from now until established\nlabour occurs.\n\nC. CIG assessments of the fetal heart rate should be repeated weekly.\n\nD. The white cell count (WCC) and C-reactive protein (CRP) levels should be assessed\nevery 2-3 days.\nE. Labour should be induced now."},"source_answer":null,"source_explanation":null,"source_answer_status":"pending_import","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["pregnan"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"tesseract","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"f0a5bd6458eea0fdbeef884e2757235d345a21b9","duplicate_group_id":"exact-f0a5bd6458ee","duplicate_sources":[{"record_id":"331aab8f08e0600aa6d3","record_type":"text_mcq","source_file":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_relative_path":"96.Handbook of Multiple Choice Questions (Vernon Marshall).pdf","source_page":356,"source_qid":"3.299"}]}',0,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
